const $=s=>document.querySelector(s);let saved;try{saved=JSON.parse(localStorage.getItem('logicquest-v1'))}catch{}let state=saved&&Array.isArray(saved.attempts)?saved:{attempts:[],completed:[],grade:'3'};state.completed=state.completed||[];const persist=()=>{try{localStorage.setItem('logicquest-v1',JSON.stringify(state))}catch{}};let view='map',current=null,choice=null,hints=0,tries=0,done=false,start;
const worlds=[['Rừng Quy Luật','Nhận diện quy luật · Tư duy quy nạp','🌲','', 'Khởi đầu hành trình'],['Lâu Đài Suy Luận','Suy luận logic · Tìm lời giải từ manh mối','🏰','castle','Thử thách tiếp theo'],['Nhà Máy Robot','Sắp xếp hành động · Tư duy thuật toán','🤖','robot','Đang xây dựng'],['Thành Phố Thám Tử','Khám phá bằng chứng · Tư duy phản biện','🕵️','city','Đang xây dựng']];
const questions=[
{id:0,w:0,q:'2 · 4 · 6 · 8 · ?',o:['9','10','12','16'],a:1,h:['Hãy so sánh hai số đứng cạnh nhau.','Từ 2 đến 4 tăng bao nhiêu? Từ 4 đến 6 thì sao?','Thử cộng cùng một số vào 8 nhé.'],why:'Mỗi số tăng thêm 2. Vì vậy 8 + 2 = 10.'},
{id:1,w:0,q:'🔴 🔵 🔵 · 🔴 🔵 🔵 · ?',o:['🔵','🟢','🔴','🟡'],a:2,h:['Em có nhận ra một nhóm hình được lặp lại không?','Hãy chia chuỗi thành từng nhóm 3 hình.','Mỗi nhóm mới bắt đầu bằng màu gì?'],why:'Nhóm đỏ – xanh – xanh được lặp lại. Nhóm tiếp theo bắt đầu bằng màu đỏ.'},
{id:2,w:0,q:'3 · 6 · 12 · 24 · ?',o:['27','36','48','30'],a:2,h:['So sánh 3 với 6, rồi 6 với 12.','Số sau gấp mấy lần số trước?','Thử dùng phép nhân ấy với 24.'],why:'Mỗi số gấp đôi số trước: 24 × 2 = 48.'},
{id:3,w:0,q:'1 · 4 · 9 · 16 · ?',o:['20','25','24','32'],a:1,h:['Tính khoảng cách giữa hai số cạnh nhau.','Các khoảng cách là 3, 5, 7. Em thấy quy luật gì?','Khoảng cách tiếp theo là số lẻ nào sau 7?'],why:'Các khoảng cách là 3, 5, 7, 9. Vì vậy 16 + 9 = 25.'},
{id:4,w:1,q:'Hộp A nặng hơn B. Hộp B nặng hơn C. Hộp nào nặng nhất?',o:['Hộp A','Hộp B','Hộp C','Bằng nhau'],a:0,h:['Giữa A và B, hộp nào nặng hơn?','B đã nặng hơn C. Vậy A so với C thì thế nào?','Hãy xếp ba hộp từ nặng đến nhẹ.'],why:'A nặng hơn B, B nặng hơn C, nên A nặng nhất.'},
{id:5,w:1,q:'An đến trước Bình. Chi đến sau Bình. Ai đến cuối cùng?',o:['An','Bình','Chi','Chưa biết'],a:2,h:['Hãy xếp An và Bình trước nhé.','Chi đứng trước hay sau Bình?','Thử viết tên ba bạn theo thứ tự đến.'],why:'Thứ tự là An, Bình, Chi. Vì vậy Chi đến cuối cùng.'},
{id:6,w:1,q:'Mọi chú mèo trong phòng đều đeo nơ. Miu là mèo trong phòng. Điều nào chắc chắn đúng?',o:['Miu đeo nơ','Miu màu trắng','Miu đang ngủ','Miu không đeo nơ'],a:0,h:['Đề bài nói điều gì về mọi chú mèo trong phòng?','Miu có thuộc nhóm mèo đó không?','Đặc điểm chung của nhóm cũng đúng với Miu.'],why:'Miu thuộc nhóm mèo trong phòng, mà mọi mèo trong phòng đều đeo nơ.'},
{id:7,w:1,q:'Có ba bạn Lan, Nam và Mai. Lan cao hơn Nam, Mai thấp hơn Nam. Ai thấp nhất?',o:['Lan','Nam','Mai','Cả ba bằng nhau'],a:2,h:['So sánh Lan với Nam trước nhé.','Mai đứng ở đâu so với Nam?','Hãy xếp từ cao nhất đến thấp nhất.'],why:'Lan cao hơn Nam, Nam cao hơn Mai. Mai thấp nhất.'}];
function count(w){return questions.filter(q=>q.w===w&&state.completed.includes(q.id)).length}function stars(){return state.attempts.filter(a=>a.correct).reduce((n,a)=>n+a.stars,0)}
const art=`<svg class="landscape" viewBox="0 0 420 250" aria-hidden="true"><circle cx="305" cy="65" r="34" fill="#f8e8a7"/><path d="M0 180Q100 70 225 169T440 138V260H0Z" fill="#cfdeb6"/><path d="M0 230Q120 143 270 194T440 170V260H0Z" fill="#b3c99d"/><path d="M195 250Q315 205 239 173Q215 158 270 140" fill="none" stroke="#f6eccd" stroke-width="21"/><g fill="#6e9a71"><path d="M90 74l-36 99h72Z"/><path d="M345 54l-40 115h80Z"/><path d="M298 93l-28 85h56Z"/></g><g fill="#8d7351"><rect x="85" y="166" width="10" height="27"/><rect x="340" y="160" width="10" height="28"/></g><text x="173" y="198" font-size="67">🦊</text><text x="259" y="119" font-size="28">✦</text><text x="51" y="212" font-size="25">🌼</text><text x="363" y="225" font-size="24">🌿</text></svg>`;
function render(){ $('#stars').textContent=stars();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent={map:'Thế giới của em',progress:'Hành trình tiến bộ',badges:'Bộ sưu tập',parent:'Góc phụ huynh'}[view];const total=state.attempts.length,correct=state.attempts.filter(a=>a.correct).length;if(view==='map')$('#content').innerHTML=`<div class="intro"><div class="eyebrow">MỘT HÀNH TRÌNH NHỎ, NGÀN KHÁM PHÁ LỚN</div><h1>Hôm nay, mình khám phá gì nhỉ? <span>☀️</span></h1><p>Những điều kỳ diệu đang chờ em. Cùng rèn tư duy qua từng cuộc phiêu lưu!</p></div><section class="hero"><div class="hero-copy"><span class="eyebrow">✦ NHIỆM VỤ DÀNH CHO EM</span><h2>Vào rừng xanh,<br>tìm điều bí ẩn!</h2><p>Quan sát một chút, suy nghĩ một chút.<br>Em đã sẵn sàng tìm ra quy luật chưa?</p><button class="btn" onclick="play(0)">Bắt đầu khám phá →</button></div>${art}</section><div class="sectiontitle"><h2>Thế giới phiêu lưu <span style="color:#a3b294;font-size:14px">/ 04</span></h2><small>Mỗi thế giới, một cách nghĩ mới</small></div><div class="grid">${worlds.map((w,i)=>`<article class="world"><div class="worldart ${w[3]}"><span class="tag">${i<2?'✦ '+w[4]:'🔒 '+w[4]}</span><span class="scene">${i===0?'🌳':i===1?'☁️':''}</span><span class="scene">${w[2]}</span><span class="scene">${i===0?'🍄':i===1?'🌲':''}</span></div><div class="worldinfo"><h3>${w[0]}</h3><p>${w[1]}</p><div class="worldfoot"><div>${i<2?`${count(i)}/4 thử thách hoàn thành`:'Một cuộc phiêu lưu mới đang đến'}<div class="track"><i style="width:${i<2?count(i)*25:0}%"></i></div></div>${i<2?`<button onclick="play(${i})">Khám phá ↗</button>`:'<span style="color:#9ca699">Sắp ra mắt</span>'}</div></div></article>`).join('')}</div><div class="bottomcards"><div class="note"><span class="icon">🦉</span><div><h3>Có bạn đồng hành bên cạnh</h3><p>Bí quá? Cú Mèo sẽ gợi ý để em tự tìm lời giải.</p></div></div><div class="note warm"><span class="icon">💡</span><div><h3>Không cần vội, cứ tò mò!</h3><p>Mỗi lần thử là một lần em học thêm điều mới.</p></div></div></div><footer>Được tạo cho những trí óc tò mò · Dành cho học sinh lớp 3–5</footer>`;else if(view==='badges')$('#content').innerHTML=`<div class="eyebrow">NHỮNG CỘT MỐC NHỎ</div><h1>Bộ sưu tập của em</h1><p>Mỗi huy hiệu ghi lại một nỗ lực đáng nhớ.</p><div class="badges">${[['🌱','Bước chân đầu tiên',state.completed.length>0],['🌲','Người bạn của rừng',count(0)===4],['🏰','Bậc thầy suy luận',count(1)===4]].map(b=>`<div class="badge" style="opacity:${b[2]?1:.45}"><span>${b[2]?b[0]:'🔒'}</span><b>${b[1]}</b><p>${b[2]?'Đã đạt được':'Tiếp tục khám phá nhé'}</p></div>`).join('')}</div>`;else $('#content').innerHTML=`<div class="eyebrow">${view==='parent'?'CÙNG CON TRƯỞNG THÀNH':'TỪNG BƯỚC TIẾN LÊN'}</div><h1>${view==='parent'?'Góc phụ huynh':'Hành trình tiến bộ'}</h1><p>Dữ liệu từ lượt chơi trên trình duyệt này.</p><div class="stats"><div class="stat"><strong>${state.completed.length}/8</strong>Thử thách đã giải</div><div class="stat"><strong>${total?Math.round(correct/total*100):0}%</strong>Lượt trả lời đúng</div><div class="stat"><strong>${state.attempts.reduce((s,a)=>s+a.hints,0)}</strong>Gợi ý đã sử dụng</div></div><div class="panel"><h2>Kỹ năng đang luyện</h2>${worlds.slice(0,2).map((w,i)=>`<div class="skill">${w[0]} <b style="float:right">${count(i)}/4</b><div class="track"><i style="width:${count(i)*25}%"></i></div></div>`).join('')}<p style="font-size:12px;color:#83907d">Tiến độ hoàn thành bài tập, không phải thang đo năng lực hay IQ.</p></div><div class="note warm" style="margin-top:20px"><span class="icon">🌻</span><div><h3>Gợi ý hoạt động cùng con</h3><p>${count(0)<count(1)?'Cùng con xếp đồ vật theo nhóm màu và hỏi: “Điều gì sẽ xuất hiện tiếp theo?”':'Cùng con xếp ba đồ vật theo kích thước và hỏi con giải thích thứ tự.'}</p></div></div><div class="panel" style="margin-top:20px"><h3>Lượt trả lời gần đây</h3>${state.attempts.slice(-6).reverse().map(a=>`<p>${worlds[a.w][0]} · ${a.correct?'✓ Đúng':'↻ Thử lại'} · ${a.hints} gợi ý · ${a.seconds} giây</p>`).join('')||'<p>Chưa có lượt chơi. Hãy bắt đầu một cuộc phiêu lưu!</p>'}<small>Gợi ý được soạn sẵn, chưa kết nối AI. Không có tài khoản hoặc đồng bộ giữa thiết bị.</small></div>`;}
function play(w){const list=questions.filter(q=>q.w===w);current=list.find(q=>!state.completed.includes(q.id))||list[0];openQuestion()}
function openQuestion(){choice=null;hints=0;tries=0;done=false;start=Date.now();$('#gamebody').innerHTML=`<div class="eyebrow">${worlds[current.w][0]} · Thử thách ${current.id%4+1}/4</div><h2>Cùng tìm lời giải nào! ✦</h2><div class="question">${current.q}</div><div class="options">${current.o.map((o,i)=>`<button onclick="choose(${i})">${o}</button>`).join('')}</div><textarea id="reason" placeholder="Em nghĩ như thế nào? (không bắt buộc)" aria-label="Giải thích cách nghĩ"></textarea><div class="tutor">🦉 <b>Cú Mèo đồng hành</b><p id="hinttext">Mình tin em có thể tự khám phá! Nếu cần, hãy nhờ mình gợi ý.</p><button id="hintbtn" onclick="hint()">Cho em một gợi ý · 0/3</button></div><div class="feedback" id="feedback" aria-live="polite"></div><button class="btn" id="check" onclick="check()">Kiểm tra đáp án</button>`;if(!$('#game').open)$('#game').showModal()}
function choose(i){if(done)return;choice=i;document.querySelectorAll('.options button').forEach((b,n)=>b.classList.toggle('selected',n===i))}
function hint(){if(hints>=3||done)return;$('#hinttext').textContent=current.h[hints++];$('#hintbtn').textContent=`${hints===3?'Đã dùng hết gợi ý':'Thêm một gợi ý'} · ${hints}/3`;$('#hintbtn').disabled=hints===3}
function check(){if(done){const next=questions.find(q=>q.w===current.w&&!state.completed.includes(q.id));if(next){current=next;openQuestion()}else{$('#game').close();render()}return}if(choice===null){$('#feedback').textContent='Em hãy chọn một đáp án trước nhé.';return}tries++;const correct=choice===current.a,earned=correct&&!state.completed.includes(current.id)?Math.max(1,3-hints-(tries>1?1:0)):0;state.attempts.push({q:current.id,w:current.w,correct,hints:tries===1?hints:Math.max(0,hints-(current.lastHints||0)),seconds:Math.round((Date.now()-start)/1000),stars:earned,reason:$('#reason').value.slice(0,500)});current.lastHints=hints;if(correct){state.completed.push(...state.completed.includes(current.id)?[]:[current.id]);done=true;$('#feedback').textContent=`Tuyệt lắm! ${current.why} ${earned?'+'+earned+' ⭐':''}`;$('#check').textContent='Tiếp tục hành trình →';$('#hintbtn').disabled=true;$('#reason').disabled=true}else $('#feedback').textContent='Chưa đúng rồi. Em thử so sánh lại các dữ kiện nhé. Cú Mèo có thể giúp em một chút!';persist();render()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('.close').onclick=()=>$('#game').close();$('#grade').value=state.grade;$('#grade').onchange=e=>{state.grade=e.target.value;persist()};render();
